) AS (
  VALUES 
    (339::BIGINT, 'Profe muy bueno. Recomendadisimo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Inspirador', 'Pocos exámenes']::TEXT[], '2024-01-29T00:00:00+00:00'::TIMESTAMPTZ, '6b23e5b9ee64e4a83a078eaa2c5c5957acc673ae3def9b8814463083030663e3'::TEXT, ARRAY[1030]::BIGINT[]),
    (339::BIGINT, 'Buen profe, comprensivo buena persona, hace amena la clase, deja muchas tareas y son bastante largas en comparacion a su valor, pero son bastante faciles, ademas a finales de semestre hay muchas clases asincronicas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-11-11T00:00:00+00:00'::TIMESTAMPTZ, 'faa104a08b40c1943a2cb831032534c4b088d5347a18f42ddd1dd0fd14d91cf6'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Es un gran profesor, tiene empatía, da las clases de buena manera, claro. Deja bastantes tareas pero nada complicadas. Si pone atención en clases y escoge un buen grupo de proyecto pasa sin complicaciones. Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Muchos proyectos grupales', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4e1190ad0d06566aedf181a3b07416d80ff4241585d1e92b70e0ce2413205ebc'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Es un profe que sabe dar la información clara. Deja mucho trabajo grupal. Por mas que intente andar al margen en las notas, siempre las deja para el final.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Muchos proyectos grupales']::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '958b2339c0eb27484f1b85b14fec7b8f9c365a35b911349c2aa02d03785206bc'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'La verdad mal profe no es, sin embargo tareas y exámenes medio tediosos pero si se logran sacar, solo que exámenes califica ridículamente mal, ni siquiera tienen sentido es muy “estricto” con eso, y los reclamos que uno le hace sobre eso ni les da respuesta, ademas que entrega notas a última hora'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Deja trabajos largos']::TEXT[], '2021-07-23T00:00:00+00:00'::TIMESTAMPTZ, 'b7797469bc85991f9fabb27fe520ef1752e122791d1d233b928f0be74953474b'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Excelente profesor, las clases van acorde a lo pide en tareas y estas no son tan pesadas, si el profe deja 5 tareas ud puede sacar un sábado, las hace y listo, no se tiene que preocupar por tareas por el resto del mes. Lo único malo es que califica casi todo un poco tarde (tipo semana 17-18)'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Respetado por los estudiantes']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '2e4a061f4aebd497e43b3b1dddcefaa7757909d0fc6f770a537c3e2c7d727f68'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'El profesor es bueno la verdad, deja bastantes trabajos pero son completamente realizables y da el tiempo suficiente. Sin embargo uno no sabe como va en el curso, se atrasa demasiado con las revisiones, ha pasado ya más de un mes desde que entregamos el primer examen parcial y no lo ha revisado.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2021-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'e99ac75858e9f96d07c8f5e38d366b61af4137e0b84e54fb566c74539f50d74d'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'El profesor es bueno pero no tiene control con la cantidad de tareas que deja, se nota que no tiene medida y deja tareas a lo loco y luego hay que andar corriendo. exámenes largos y tediosos. Pasar el curso es complicado por la cantidad de tiempo que demanda.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas']::TEXT[], '2021-05-04T00:00:00+00:00'::TIMESTAMPTZ, '93e0ea2ce45c1950260a953404c9e3450efef9a6b674353d980f85d20bd273f0'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Esten listos para no tener tiempo para hacer trabajos de otros cursos, él cuenta los sábados, domingos y feriados como dias para hacer trabajos. Nos dejó un exámen super largo un jueves en la tarde y habia que entregarlo un Marte antes de las 3pm (ACLARO: él contó sabado, domingo y lunes {FERIADO})'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-03T00:00:00+00:00'::TIMESTAMPTZ, '72936b459497e4051ddfa2ff1f58e2396d053d0f8e8fc7ffac245bcd7209aa23'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-04T00:00:00+00:00'::TIMESTAMPTZ, '3b2eb6dc388006cc1d50fd7c54d3238d40438833ca895268f241e24310e8bd7c'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-02-02T00:00:00+00:00'::TIMESTAMPTZ, 'ca23bf2017729bfa8875a8874681d7d1e852db0edbd153ee83242f722626060b'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Como profe en modalidad virtual es pésimo, siempre revisa los trabajos para último momento y nunca se sabe cómo va uno en el curso. No recibimos clases durante 3 semanas seguidas, se pasa muy fácil, pero no se aprende nada.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a75695a51659c6579c5a8cc709ae7e23bba81c349fcf47f8873ca1e76e79bd70'::TEXT, ARRAY[1056]::BIGINT[]),
    (339::BIGINT, 'De los mejores profes del TEC, es increíble. Sabe enseñar! Los proyectos y tareas que deja toman tiempo pero tampoco lo asfixian a uno. Explicaciones de la materia, del proyecto, todo super claro.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Aspectos de calificación claros', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-11-28T00:00:00+00:00'::TIMESTAMPTZ, '36ee30d27bcf1e662fa85fe44bfa98b362676a7a1567564cd03fd15dc1aeec0e'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'En pocas palabras sabe demasiado y me encanta como explica, a pesar de que es un curso que pinta ser "aburrido" con él no es así'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2019-10-11T00:00:00+00:00'::TIMESTAMPTZ, '1ad6d0fd0de96b014fce3d4682048599b08db1c839b1234b26f457d6a4a06cb5'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Es un excelente profesor, explica muy bien, los proyectos no son volados, ni tampoco fáciles, mas bien deja proyectos de un buen nivel, sabe mucho sobre el curso y me encanto la forma de explicar de el'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2019-06-17T00:00:00+00:00'::TIMESTAMPTZ, '90063d7caf2af8611ec8c2596c593cb484769492ef28698035aab259be6a166b'::TEXT, ARRAY[1039]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-07-12T00:00:00+00:00'::TIMESTAMPTZ, 'ba9e9f2a520ef6245bd2832a49811ccaeb031c366769d1211331686edcc3a3e2'::TEXT, ARRAY[1030]::BIGINT[]),
    (339::BIGINT, 'Sus trabajos son completamente realizables, estan muy acordes a los contenidos del curso y es flexible con el estudiante, lo cual ayuda montones. Si deja bastante tarea, pero eso te ayuda con el promedio al final de cuentas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-04T00:00:00+00:00'::TIMESTAMPTZ, '529c481fd9323a4199ee7cafdad8c5f0653839e2019473b57f860e22924f5f8c'::TEXT, ARRAY[1056]::BIGINT[]),
    (339::BIGINT, 'Hay que trabajar para sacar el curso, pero los trabajos son realizables.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-08T00:00:00+00:00'::TIMESTAMPTZ, '02f8bc98cff0ca63c86443ec4395937152ff576a24e22b0fccd877d04f1a0a03'::TEXT, ARRAY[1056, 1047]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-25T00:00:00+00:00'::TIMESTAMPTZ, '1b93f1a59bcd651928c123b6ff2a07b567bd3d76ca5d93a14e1868e82423849c'::TEXT, ARRAY[1031]::BIGINT[]),
    (339::BIGINT, 'no explica muy bien'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'cfcfbb1889ba77ec4240745b4a03282a5483fbd33809c37f6c7fed61d1b55e9d'::TEXT, ARRAY[1035, 1029]::BIGINT[]),
    (339::BIGINT, 'Tiene mucho conocimiento pero no sabe explicar,los proyectos no los deja el y los califica otros. Aparte no da mucho apoyo al estudiante, el mismo (estudiante) debe adquirir conocimientos de otro lado si desea pasar,'::TEXT, 6.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-29T00:00:00+00:00'::TIMESTAMPTZ, '7f8d979e3dd419727f6503f86f580af8b9029a7aa0f716cf9e2dc18e2daa457f'::TEXT, ARRAY[1035, 1029]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '0c1c43f2509a130215b34ac9af9613eae8061b75f6475f082722cff5f7cd7a4d'::TEXT, ARRAY[1043]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '77acf139b19bcc8efb229c377b204a319e2e5f70df897b480c46ede5549eb42d'::TEXT, ARRAY[2965]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '1026cbff73934a04bccb024e446492d6e407d59668ac05cdba5668ad033c7be2'::TEXT, ARRAY[1043]::BIGINT[]),
    (339::BIGINT, 'Deja proyectos bastante simples, pero trabajos de investigación con exposición que son un dolor. Es muy buena nota y muy comprensivo con el estudiante en caso de situaciones externas. Siempre da más tiempo en caso de ser necesario.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '464daf814df784cf89a0764b7fad85ff2f719edc9033399c57a9c7e67bca33cc'::TEXT, ARRAY[2965]::BIGINT[]),
    (339::BIGINT, 'No sabe explicar, conoce los temas pero no los sabe transmitir, los proyectos que hace, los evaluan otros profesores para meterles nivel, porque no les da buena dificultad, le da prioridad en calificación e interes a los trabajos que en realidad menos importan en el curso... (como exposiciones)'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '42d8ddec90e9239f93019e2873865d1bfd6c5c0f5140c9d87e7c8d54c9758c7d'::TEXT, ARRAY[1043]::BIGINT[]),
    (339::BIGINT, 'Aunque se nota que lo intenta, no se le entiende mucho, uno termina buscando en Google los temas del curso. Proyectos de buen nivel, ni muy fáciles ni muy difíciles, ayuda mucho y es muy comprensivo, no le importa quedarse hasta tarde ayudando a un alumno. Califica justo y desglosa la nota.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'ef4cb1c6b53f3c3a1f338f6c28f87cb6eff91bdd9316ef43f591a489ab66cc1c'::TEXT, ARRAY[2965]::BIGINT[]),
    (339::BIGINT, 'Deja proyectos que se pueden terminar'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'a232481ace67cab74e23fcf65ecd1e21ba4b1cd5fcd6ac3af2c9d125aac750be'::TEXT, ARRAY[1043]::BIGINT[]),
    (339::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-15T00:00:00+00:00'::TIMESTAMPTZ, '5b72ca1bbdeed3ece378afb1ad39512638da13e1367094faabc0b472f72767b5'::TEXT, ARRAY[1043]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
